    const count = text.split(o).length - 1
    if (count !== 1) throw new Error(`${rel} replacement #${i + 1}: expected 1 match, got ${count}`)
    text = text.replace(o, n)
  })
  fs.writeFileSync(file, text, 'utf8')
  console.log(`patched ${rel}: ${pairs.length} replacements (${crlf ? 'CRLF' : 'LF'})`)
}

