    hasDistrictProfileText: document.body.innerText.includes('太湖生态水乡'),
    kpiHasFiltered: document.body.innerText.includes('490') || document.body.innerText.includes('480')
  }))
  console.log(label, JSON.stringify(result), 'errors:', errors.length ? JSON.stringify(errors.slice(0, 3)) : 'none')
  await page.close()
}

